// React
import React, { useState, useEffect } from "react";
import Loader from "react-loader-spinner";
import Select from "react-select";
import { FormattedMessage } from "react-intl";
import moment from "moment";

// Redux
import { connect } from "react-redux";
import {
	fetchVisaIssuerSummary,
	downloadVisaIssuerCsvSummary,
	fetchVisaIssuerSummaryStats,
	downloadAutomaticVisaIssuerCsvSummary,
} from "../../../../actions/filesets";

// components
import { Card, CardBody, CardHeader, Col, Row, Table, Button, Alert } from "reactstrap";
import PostingTable from "../../../../components/PostingTable";
import PostingTableHeader from "../../../../components/PostingTableHeader";
import ErrorMessage from "../../../../components/ErrorMessage";

const visaIssuerSummary = ({
	// action creators
	fetchVisaIssuerSummary,
	downloadVisaIssuerCsvSummary,
	downloadAutomaticVisaIssuerCsvSummary,
	fetchVisaIssuerSummaryStats,
	match                                 : { params: { date: settlementDate } },
	// props from state
	selectedAffiliateCode,
	download_status,
	visaIssuerSummary,
	visaIssuerSummaryError,
}) => {
	const [ isDownloadError, setIsDownloadError ] = useState(false);
	const [ selectedDownloadFormat, setSelectedDownloadFormat ] = useState({
		label : "Choose Format",
		value : "Choose Format",
	});
	const [ dateOnFilename, setDateOnFilename ] = useState(moment(settlementDate).format("DDMMYY"));
	useEffect(
		() => {
			setDateOnFilename(moment(settlementDate).format("DDMMYY"));
			fetchVisaIssuerSummary(settlementDate);
			// fetchVisaIssuerSummaryStats(settlementDate);
		},
		[ settlementDate ],
	);

	useEffect(
		() => {
			fetchVisaIssuerSummary(settlementDate);
			// fetchVisaIssuerSummaryStats(settlementDate);
		},
		[ selectedAffiliateCode ],
	);

	const handleDownloadVisaPostingCsv = (downloadFormat) => {
		if (downloadFormat.value === "Choose Format") setIsDownloadError(true);
		if (downloadFormat.value === "Automatic")
			downloadAutomaticVisaIssuerCsvSummary(settlementDate, dateOnFilename, selectedAffiliateCode);
		if (downloadFormat.value === "Manual")
			downloadVisaIssuerCsvSummary(settlementDate, dateOnFilename, selectedAffiliateCode);
	};

	const FileDownloadFormats = [ { label: "Automatic", value: "Automatic" }, { label: "Manual", value: "Manual" } ];

	return (
		<div className='animated fadeIn'>
			{isDownloadError && (
				<Alert color='danger' toggle={() => setIsDownloadError(false)}>
					{"Error unable to download. Please select a download format!"}
				</Alert>
			)}
			<Row>
				<Col lg={12}>
					<Card>
						<CardHeader className={"d-flex w-100 justify-content-between align-items-center"}>
							<strong>{settlementDate} Posting Summary</strong>
							<div style={{ width: "73%" }} className={"d-flex justify-content-end align-items-center"}>
								{visaIssuerSummary && (
									<React.Fragment>
										<span style={{ width: "20%" }}>
											<Select
												className={"mx-1"}
												onChange={(selectedDownloadFormat) =>
													setSelectedDownloadFormat(selectedDownloadFormat)}
												value={selectedDownloadFormat}
												options={FileDownloadFormats}
											/>
										</span>

										<Button
											type='button'
											className={"float-right mb-0 btn-sm mx-1 py-2"}
											onClick={() => handleDownloadVisaPostingCsv(selectedDownloadFormat)}
											color={"success"}
											download={"" + 1 + ".csv"}
										>
											<span className={"d-flex px-2 justify-content-center align-items-center"}>
												<i className='fa fa-download' />&nbsp;
												{download_status && (
													<Loader
														type='ThreeDots'
														color='#FFF'
														height={20}
														width={20}
														style={{ textAlign: "center" }}
													/>
												)}
												{!download_status && (
													<FormattedMessage id='Download CSV' defaultMessage='Download CSV' />
												)}
											</span>
										</Button>
									</React.Fragment>
								)}
							</div>
						</CardHeader>

						<CardBody>
							{/* Handle loading */}
							{!visaIssuerSummaryError &&
							!visaIssuerSummary && (
								<article className='d-flex justify-content-center align-items-center'>
									<div>
										<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
									</div>
								</article>
							)}

							{/* Handle 404 not found */}
							{visaIssuerSummaryError &&
							!visaIssuerSummary && <ErrorMessage message={visaIssuerSummaryError.data.message} />}

							{!visaIssuerSummaryError &&
							visaIssuerSummary &&
							visaIssuerSummary.data &&
							visaIssuerSummary.data[0] &&
							visaIssuerSummary.data[0].records.length === 0 && (
								<ErrorMessage message={"There are no posting summary entries for this date"} />
							)}

							{/* Handle display content */}
							{!visaIssuerSummaryError &&
							visaIssuerSummary &&
							visaIssuerSummary.data &&
							visaIssuerSummary.data[0] &&
							visaIssuerSummary.data[0].records.length > 0 && (
								<Table hover bordered striped responsive size='sm' style={{ minWidth: "180%" }}>
									<thead>
										<PostingTableHeader />
									</thead>
									<tbody>
										<PostingTable dataRecords={[ ...visaIssuerSummary.data ]} />
									</tbody>
								</Table>
							)}
						</CardBody>
					</Card>
				</Col>
			</Row>
		</div>
	);
};

const mapStateToProps = (state) => {
	return {
		selectedAffiliateCode  : state.fileSets.selectedAffiliateCode,
		visaIssuerSummary      : state.fileSets.visaIssuerSummary,
		visaIssuerSummaryError : state.fileSets.visaIssuerSummaryError,
		download_status        : state.fileSets.download_status,
	};
};

export default connect(mapStateToProps, {
	fetchVisaIssuerSummary,
	downloadVisaIssuerCsvSummary,
	downloadAutomaticVisaIssuerCsvSummary,
	fetchVisaIssuerSummaryStats,
})(visaIssuerSummary);
